SELECT "accountid", "sk_brokerid", "sk_customerid", "status", "accountdesc", "taxstatus", "iscurrent", "batchid", "effectivedate", "enddate", CAST(ROW_NUMBER() OVER (ORDER BY accountid, effectivedate) AS INT) AS "sk_accountid" FROM (SELECT TRY_CAST((CAST(a.CA_ID AS INT)) AS INT) AS "accountid", TRY_CAST((COALESCE(CAST(a.CA_B_ID AS INT), 0)) AS INT) AS "sk_brokerid", TRY_CAST((CAST(c.C_ID AS INT)) AS INT) AS "sk_customerid", TRY_CAST((CASE WHEN act.ActionType = 'CLOSEACCT' THEN 'closed' ELSE 'active' END) AS TEXT) AS "status", TRY_CAST((a.CA_NAME) AS TEXT) AS "accountdesc", TRY_CAST((CAST(COALESCE(a.CA_TAX_ST, 0) AS INT)) AS INT) AS "taxstatus", TRY_CAST((TRUE) AS BOOLEAN) AS "iscurrent", TRY_CAST((CAST(NULL AS INT)) AS INT) AS "batchid", TRY_CAST((CAST(SUBSTRING(act.ActionTS, 1, 10) AS DATE)) AS DATE) AS "effectivedate", TRY_CAST((CASE WHEN act.ActionType = 'CLOSEACCT' THEN CAST(act.ActionTS AS DATE) ELSE CAST('9999-12-31' AS DATE) END) AS DATE) AS "enddate" FROM "Source"."AccountXML" AS a INNER JOIN "Source"."CustomerXML" AS c ON a.Customer_Id = c.Customer_Id INNER JOIN "Source"."ActionXML" AS act ON c.Action_Id = act.Action_Id WHERE act.ActionType IN ('NEW', 'ADDACCT', 'UPDACCT', 'CLOSEACCT'));
